Clase Caja
    Publico Definir contenido Como Entero;
FinClase

Proceso CompararObjetos
    Definir bandera Como Entero;
    Definir a Como Caja;
    Definir b Como Caja;
    Leer bandera;
    a <- Nuevo Caja();
    Si bandera = 1 Entonces
        b <- a;
    SiNo
        b <- Nuevo Caja();
    FinSi
    Si a = b Entonces
        Escribir 1;
    SiNo
        Escribir 0;
    FinSi
FinProceso
